<?php
class FPDF {
    protected string $buffer = '';
    public function AddPage(): void { $this->buffer .= "\n"; }
    public function SetFont($family, $style = '', $size = 12): void {}
    public function Cell($w, $h = 0, $txt = '', $border = 0, $ln = 0, $align = '', $fill = false, $link = ''): void { $this->buffer .= $txt . "\n"; }
    public function Ln($h = null): void { $this->buffer .= "\n"; }
    public function Output($dest = 'I', $name = 'doc.pdf'): void {
        header('Content-Type: application/pdf');
        header('Content-Disposition: attachment; filename="' . $name . '"');
        echo "%PDF-1.1\n% Simple placeholder PDF generated by compatibility layer\n";
        echo $this->buffer;
    }
}
